def merge_intervals(iv):
    if not iv:
        return []
    iv = sorted(iv, key=lambda x: x[0])
    merged = [list(iv[0])]
    for start, end in iv[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
```

